if '/cad-v2560.js' not in h:
    h=h.replace('</body>','<script src="/cad-v2560.js"></script></body>',1)
html.write_text(h,encoding='utf-8')
js=r'''(function(){
'use strict';
function ready(f){document.readyState==='loading'?document.addEventListener('DOMContentLoaded',f,{once:true}):f()}
let thickOn=false, thickGeom=[];
const V=()=>new THREE.Vector3();
function unit(v){const f=typeof unitFactor==='function'?unitFactor():1,u=document.getElementById('unit')?.value||'mm';return (v*f).toFixed(Math.abs(v*f)>=100?2:3)+' '+u}
function info(t){const e=document.getElementById('mgMeasureInfo2560');if(e)e.innerHTML=t}
function smartBtn(){return document.getElementById('mgSmartMeasure2550')}
function smartActive(){const b=smartBtn();return !!(b&&b.classList.contains('on'))}
function smartOff(){const b=smartBtn();if(b&&smartActive())b.click()}
function classicOff(){if(window.measureOn&&window.toggleMeasure)window.toggleMeasure()}
function clearThick(){thickGeom.forEach(o=>{scene.remove(o);if(o.geometry)o.geometry.dispose();if(o.material)o.material.dispose()});thickGeom=[]}
function setActive(name){['mgRef2560','mgPoint2560','mgThick2560'].forEach(id=>{const b=document.getElementById(id);if(b)b.classList.remove('mgm-active')});const m={ref:'mgRef2560',point:'mgPoint2560',thick:'mgThick2560'}[name];if(m){const b=document.getElementById(m);if(b)b.classList.add('mgm-active')}}
function stopAll(){smartOff();classicOff();thickOn=false;clearThick();setActive(null)}
function hideLegacySmart(){const b=smartBtn();if(!b)return;let p=b.parentElement;while(p&&p.parentElement&&p.parentElement.id!=='tools')p=p.parentElement;if(p&&p.parentElement&&p.parentElement.id==='tools')p.style.display='none'}
function hitAt(ev){const r=canvas.getBoundingClientRect(),m=new THREE.Vector2(((ev.clientX-r.left)/r.width)*2-1,-((ev.clientY-r.top)/r.height)*2+1),rr=new THREE.Raycaster();rr.setFromCamera(m,camera);return rr.intersectObjects(group.children.filter(o=>o.visible),true)[0]||null}
function opposite(hit){if(!hit.face)return null;const n=hit.face.normal.clone().transformDirection(hit.object.matrixWorld).normalize(),span=Math.max(baseDims.x||1,baseDims.y||1,baseDims.z||1,1),eps=span*1e-5;function shoot(dir){const rr=new THREE.Raycaster(hit.point.clone().addScaledVector(dir,eps*8),dir,eps*4,span*4);const hs=rr.intersectObjects(group.children.filter(o=>o.visible),true).filter(x=>x.distance>eps*4);return hs.length?hs[0]:null}const a=shoot(n.clone().negate()),b=shoot(n.clone());if(a&&b)return a.distance<=b.distance?a:b;return a||b}
function addLine(points,color,width){const g=new THREE.BufferGeometry().setFromPoints(points),m=new THREE.LineBasicMaterial({color:color,depthTest:false,linewidth:width||1}),o=new THREE.Line(g,m);o.renderOrder=999;scene.add(o);thickGeom.push(o);return o}
function drawCaliper(a,b,n){clearThick();const span=Math.max(baseDims.x||1,baseDims.y||1,baseDims.z||1,1),view=new THREE.Vector3();camera.getWorldDirection(view);let t=n.clone().cross(view);if(t.lengthSq()<1e-8)t=n.clone().cross(new THREE.Vector3(0,1,0));if(t.lengthSq()<1e-8)t=n.clone().cross(new THREE.Vector3(1,0,0));t.normalize();const jaw=span*.075,stem=span*.028,orange=0xffa43a,yellow=0xffdf66;addLine([a.clone().addScaledVector(t,-jaw),a.clone().addScaledVector(t,jaw)],orange,3);addLine([b.clone().addScaledVector(t,-jaw),b.clone().addScaledVector(t,jaw)],orange,3);addLine([a,b],yellow,3);const d=b.clone().sub(a).normalize();addLine([a.clone().addScaledVector(t,jaw),a.clone().addScaledVector(t,jaw).addScaledVector(d,stem)],orange,3);addLine([b.clone().addScaledVector(t,-jaw),b.clone().addScaledVector(t,-jaw).addScaledVector(d,-stem)],orange,3)}
function install(){const tools=document.getElementById('tools');if(!tools||document.getElementById('mgMeasureModes2560'))return;hideLegacySmart();const style=document.createElement('style');style.textContent=`#mgMeasureModes2560{margin-top:8px}.mgm-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.mgm-card{border:1px solid rgba(255,255,255,.16);border-radius:12px;padding:7px;background:rgba(255,255,255,.035)}.mgm-card b{display:block;font-size:12px;margin-bottom:5px}.mgm-card small{display:block;opacity:.72;line-height:1.25;margin-top:4px}.mgm-ref{border-left:4px solid #55b7ff}.mgm-point{border-left:4px solid #67d78f}.mgm-thick{border-left:4px solid #ff9f43}.mgm-thick button{font-size:15px}.mgm-active{outline:2px solid currentColor;box-shadow:0 0 0 2px rgba(255,255,255,.08) inset}.mgm-wide{grid-column:1/-1}.mgm-caliper{font-size:17px;letter-spacing:-1px}`;document.head.appendChild(style);const w=document.createElement('div');w.id='mgMeasureModes2560';w.innerHTML='<div class="sep"></div><div class="head">ÖLÇÜM MODLARI</div><div class="mgm-grid"><div class="mgm-card mgm-ref"><b>🔷 REFERANSLI</b><button id="mgRef2560">AKILLI ÖLÇÜM</button><small>Referans → 1. nokta → 2. nokta</small></div><div class="mgm-card mgm-point"><b>🟢 NOKTA–NOKTA</b><button id="mgPoint2560">MESAFE</button><small>İki noktayı doğrudan ölç</small></div><div class="mgm-card mgm-thick mgm-wide"><b>🟧 KALINLIK / KUMPAS</b><button id="mgThick2560"><span class="mgm-caliper">┫━━━━┣</span> KALINLIK</button><small>Tek dokunuş: iki büyük kumpas çenesi karşı yüzleri otomatik yakalar.</small></div></div><div class="row" style="margin-top:7px"><button id="mgClear2560">ÖLÇÜMÜ TEMİZLE</button></div><div class="small" id="mgMeasureInfo2560">Her mod ayrı görünür ve aynı anda yalnızca biri çalışır.</div>';tools.appendChild(w);const rb=document.getElementById('mgRef2560'),pb=document.getElementById('mgPoint2560'),tb=document.getElementById('mgThick2560');rb.onclick=e=>{e.preventDefault();classicOff();thickOn=false;clearThick();if(!smartActive()){const b=smartBtn();if(b)b.click()}setActive('ref');info('<b>🔷 REFERANSLI:</b> Referans kenar/yüzey → 1. nokta → 2. nokta')};pb.onclick=e=>{e.preventDefault();smartOff();thickOn=false;clearThick();if(!window.measureOn&&window.toggleMeasure)window.toggleMeasure();setActive('point');info('<b>🟢 NOKTA–NOKTA:</b> İlk noktayı, sonra ikinci noktayı seç.')};tb.onclick=e=>{e.preventDefault();smartOff();classicOff();clearThick();thickOn=!thickOn;setActive(thickOn?'thick':null);info(thickOn?'<b>🟧 KALINLIK:</b> Ölçmek istediğin dış yüzeye yalnızca bir kez dokun. Kumpas çeneleri otomatik açılır.':'KALINLIK kapalı.')};document.getElementById('mgClear2560').onclick=e=>{e.preventDefault();stopAll();if(window.clearMeasure)window.clearMeasure();info('Ölçümler temizlendi. Bir ölçüm modu seç.')};canvas.addEventListener('click',ev=>{if(!thickOn||ev.clientY<58)return;const h=hitAt(ev);if(!h)return;ev.preventDefault();ev.stopImmediatePropagation();const o=opposite(h);if(!o){clearThick();info('<b>Karşı yüz bulunamadı.</b> Katı/kapalı bölgenin dış yüzeyine dokun.');return}const n=h.face.normal.clone().transformDirection(h.object.matrixWorld).normalize();drawCaliper(h.point.clone(),o.point.clone(),n);const d=h.point.distanceTo(o.point);info('<b>🟧 KALINLIK: '+unit(d)+'</b><br><small>Tek dokunuşla yüzey normalinde karşı yüz yakalandı. Büyük kumpas çeneleri ölçüm yerini gösteriyor.</small>');if(navigator.vibrate)navigator.vibrate([20,35,20])},true)}
function init(){install();window.MG_CAD_V2560={version:'2.5.6',baseline:'2.5.5',referenceVersion:'2.5.5',exclusiveMeasurementModes:true,visualModeSeparation:true,oneTapThickness:true,largeCaliperJaws:true}}
ready(init)
})();'''
(AS/'cad-v2560.js').write_text(js,encoding='utf-8')
print('v2.5.6 separated measurement modes + one-tap large caliper thickness')
